def _solve():
    houses = range(5)
    first, middle = 0, 2

    def right_of(a, b):
        return a == b + 1

    def next_to(a, b):
        return abs(a - b) == 1

    for red, green, ivory, yellow, blue in permutations(houses):
        if not right_of(green, ivory):
            continue
        for eng, spa, ukr, nor, jap in permutations(houses):
            if eng != red or nor != first or not next_to(nor, blue):
                continue
            for coffee, tea, milk, oj, water in permutations(houses):
                if coffee != green or ukr != tea or milk != middle:
                    continue
                for dance, paint, read, football, chess in permutations(houses):
                    if paint != yellow or football != oj or jap != chess:
                        continue
                    for dog, snail, fox, horse, zebra in permutations(houses):
                        if spa != dog or snail != dance:
                            continue
                        if not next_to(read, fox) or not next_to(paint, horse):
                            continue
                        names = {eng: "Englishman", spa: "Spaniard", ukr: "Ukrainian",
                                 nor: "Norwegian", jap: "Japanese"}
                        return names[water], names[zebra]
    return None


def drinks_water():
    return _solve()[0]


def owns_zebra():
    return _solve()[1]
